SELECT sum(1) AS sample_count, sum(bs.weight) AS units_count, sum((bs."out.electricity.total.energy_consumption" - bs."out.natural_gas.total.energy_consumption") * bs.weight) AS elec_minus_gas FROM resstock_2024_amy2018_release_2_metadata AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND bs.bldg_id IN (SELECT bs.bldg_id FROM resstock_2024_amy2018_release_2_metadata AS bs WHERE bs.upgrade IN (1) AND bs.applicability = true GROUP BY bs.bldg_id HAVING count(distinct(bs.upgrade)) = 1) AND bs."in.state" = 'CO' AND bs.bldg_id IN (13, 16, 33, 196, 5224, 7321, 7923, 12142)